require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$bid=branch_id();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete'])){verify_csrf();$pdo->prepare('UPDATE products SET is_active=0 WHERE id=? AND branch_id=?')->execute([(int)$_POST['delete'],$bid]);flash('success','Produk dinonaktifkan.');redirect('/owner/produk.php');}$s=$pdo->prepare('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.branch_id=? ORDER BY p.is_active DESC,p.name');$s->execute([$bid]);$rows=$s->fetchAll();$pageTitle='Manajemen Produk';$active='produk';include __DIR__.'/../includes/header.php';?>
<section class="card"><div class="card-head"><h2>Produk cabang ini</h2><a class="btn primary" href="produk_form.php"><i class="bi bi-plus-lg"></i> Tambah produk</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Modal</th><th>Stok</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><strong><?=e($p['name'])?></strong><br><small><?=e($p['sku'])?></small></td><td><?=e($p['category'])?></td><td><?=rupiah($p['selling_price'])?></td><td><?=rupiah($p['purchase_price'])?></td><td class="<?=$p['stock']<=$p['min_stock']?'low-stock':''?>"><?=$p['stock']?></td><td><span class="badge <?=$p['is_active']?'':'off'?>"><?=$p['is_active']?'Aktif':'Nonaktif'?></span></td><td><div class="actions"><a class="btn soft sm" href="produk_form.php?id=<?=$p['id']?>">Edit</a><?php if($p['is_active']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn danger sm" name="delete" value="<?=$p['id']?>">Nonaktifkan</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/../includes/footer.php';?>
